//go:build ignore

// Copy into upstream converter/musicxml and run TestCodexMusicXMLHeader.
package musicxml
import("bytes";"encoding/json";"fmt";"math/rand";"os";"path/filepath";"testing";"github.com/shibukawa/tinygodriver/encoding/xmlro")
func TestCodexMusicXMLHeader(t *testing.T){root:=os.Getenv("BDF_FIXTURE_ROOT");if root==""{t.Fatal("BDF_FIXTURE_ROOT required")};samples:=[][]byte{};for _,name:=range []string{"ode_to_joy.mxl","ode_to_joy.musicxml","twinkle_timewise.musicxml","minuet.musicxml"}{b,e:=os.ReadFile(filepath.Join("testdata",name));if e!=nil{t.Fatal(e)};samples=append(samples,b)};r:=rand.New(rand.NewSource(513232));fragments:=[]string{`<work><work-title> Main Title </work-title></work>`,`<movement-title> Part Two </movement-title>`,`<identification><creator type="composer"> J. S. Bach </creator><creator type="poet"> Writer </creator><rights>CC</rights></identification>`,`<credit><credit-type>title</credit-type><credit-words> Typed Title </credit-words></credit>`,`<credit><credit-type>composer</credit-type><credit-words>Typed</credit-words><credit-words> Name</credit-words></credit>`,`<credit><credit-type>poet</credit-type><credit-words> Poet </credit-words></credit>`,`<credit><credit-words justify="center" font-size="22">Large Title</credit-words></credit>`,`<credit><credit-words halign="center" font-size="16">Small Title</credit-words></credit>`,`<credit><credit-words justify="right">Composer Name</credit-words></credit>`,`<credit><credit-words justify="center" font-size="NaN">Nan Title</credit-words></credit>`,`<credit><credit-words justify="center" font-size="-Inf">Inf Title</credit-words></credit>`,`<credit><credit-words justify="center" font-size="1e309">Huge Title</credit-words></credit>`,`<credit page="2"><credit-words justify="center">second page</credit-words></credit>`,`<part-list><score-part id="P1"><part-name>Clarinet</part-name><part-abbreviation>Cl.</part-abbreviation><midi-instrument id="I1"><midi-channel>3</midi-channel><midi-program>72</midi-program><midi-unpitched>30</midi-unpitched><volume>63.5</volume><pan>-45</pan></midi-instrument></score-part></part-list>`,`<part-list><score-part id="P2"><part-name print-object="no">Hidden</part-name><part-abbreviation>X</part-abbreviation></score-part></part-list>`,`<part-list><score-part id="P3"><part-name>Piano</part-name><part-name-display><display-text>Piano </display-text><accidental-text>sharp</accidental-text></part-name-display></score-part></part-list>`,`<part-list><score-part id="P5"><part-name>X</part-name><midi-instrument><volume>1e308</volume></midi-instrument></score-part></part-list>`,`<part-list><score-part id="P4"><part-name>Test</part-name><midi-instrument><midi-channel>55</midi-channel><midi-program>-1</midi-program><volume>-4</volume><pan>99</pan></midi-instrument></score-part></part-list>`};for i:=0;i<1500;i++{s:="<score-partwise>";for j:=0;j<1+r.Intn(12);j++{s+=fragments[r.Intn(len(fragments))]};samples=append(samples,[]byte(s+"</score-partwise>"))}
 out:=[]any{};for _,input:=range samples{data,e:=readInput(bytes.NewReader(input),int64(len(input)));if e!=nil{t.Fatal(e)};data,_=toUTF8(data);rd:=newXMLReader(data);state:=newReader();depth:=0;for{k,e:=rd.Next();if e!=nil{t.Fatal(e)};if k==xmlro.EOF{break};if k==xmlro.StartElement {if depth==0{depth=1;continue};n,e:=readNode(rd);if e!=nil{t.Fatal(e)};state.header(n)} else if k==xmlro.EndElement{break}};state.setCredits();parts:=[]any{};for _,p:=range state.parts{inst:=[]any{};for _,v:=range p.instruments{inst=append(inst,[]any{v.id,v.channel,v.program,v.unpitched,v.volume,v.pan})};parts=append(parts,[]any{p.id,p.part.Name,p.part.Abbrev,p.trackName,inst})};warn:=[]string{};warn=append(warn,state.warnings...);s:=state.score;out=append(out,map[string]any{"input":input,"want":[]any{s.Title,s.Subtitle,s.Composer,s.Lyricist,s.Arranger,s.Rights,parts,warn}})};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/musicxml/header.json"),b,0644);e!=nil{t.Fatal(e)};fmt.Printf("%d headers\n",len(out))}
